import {
  WebSocketGateway,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
  OnGatewayConnection,
} from '@nestjs/websockets';
import { Socket } from 'socket.io';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { RedisService } from '../redis/redis.service';

@WebSocketGateway({ cors: true })
export class AlertsGateway implements OnGatewayConnection {
  constructor(
    @InjectQueue('panic-alerts') private readonly alertsQueue: Queue,
    private readonly redisService: RedisService,
  ) {}

  /**
   * Cada vez que un móvil o web se conecta, verificamos si es una reconexión
   * tras una caída de cobertura.
   */
  async handleConnection(client: Socket) {
    const userId = client.handshake.query.userId as string;
    if (userId) {
      const existingAlertId = await this.redisService.getActiveAlert(userId);
      if (existingAlertId) {
        // Si existe, le avisamos al cliente para que restaure su UI
        client.emit('alert_restored', {
          alertId: existingAlertId,
          message: 'Tu alerta sigue activa en nuestros sistemas.',
        });
      }
    }
  }

  @SubscribeMessage('send_panic_alert')
  async handlePanicAlert(@MessageBody() payload: any, @ConnectedSocket() client: Socket) {
    // 1. Blindamos la alerta en Redis inmediatamente
    // Guardamos 'PENDING' hasta que el worker nos dé el UUID real de la DB
    await this.redisService.setActiveAlert(payload.userId, 'PENDING');

    // 2. Metemos en la cola de procesamiento pesado
    const job = await this.alertsQueue.add('process-alert', payload);

    return { status: 'RECEIVED', jobId: job.id };
  }
}
